def maxSlidingWindow(nums, k):
    from collections import deque
    dq = deque()  # holds indices, values decreasing
    result = []
    for i, n in enumerate(nums):
        while dq and nums[dq[-1]] < n:
            dq.pop()
        dq.append(i)
